/**
 * REST API Integration Page
 * Handles token management, form interactions
 */

(function($) {
  'use strict';

  // REST API Integration Functions
  window.ContactINIntegration = {
    /**
     * Toggle REST API service enable/disable (Using Global Toggle Utility)
     */
    toggleRestApiService: function(btn) {
      // Fallback implementation only; primary binding happens on document ready when global utility exists
      if (typeof window.cinInitToggleButton === 'function') {
        return;
      }

      var $btn = $(btn);
      var enabled = $btn.data('enabled') == 1;
      $btn.prop('disabled', true);
      $.post(ajaxurl, {
        action: 'contactin_toggle_restapi_service',
        nonce: contactinIntegrationL10n.nonce,
        enabled: enabled ? 0 : 1
      }, function(response) {
        $btn.prop('disabled', false);
        if (response.success) {
          $btn.data('enabled', response.data.enabled ? 1 : 0);
          $btn.html(response.data.button);
          var $label = $('#contactin-restapi-status-label');
          $label.text(response.data.label);
          $label.css('color', response.data.enabled ? '#27ae60' : '#d63638');
          ContactINIntegration.setActionItemsEnabled(response.data.enabled);
        } else {
          // Show error message (e.g., when file attachment requires REST API)
          alert(response.data.message || 'Failed to update status.');
          // Keep button in its current state if operation failed
        }
      });
    },
    /**
     * Enable or disable all REST API action items
     */
    setActionItemsEnabled: function(enabled) {
      // Copy button
      var $copyBtn = $('#contactin-copy-base-url');
      $copyBtn.prop('disabled', !enabled);
      $copyBtn.toggleClass('disabled', !enabled);

      // Generate Token button
      var $genBtn = $('#contactin-generate-token-btn');
      $genBtn.prop('disabled', !enabled);
      $genBtn.toggleClass('disabled', !enabled);

      // Test Connection button
      var $testBtn = $('#test_submit');
      $testBtn.prop('disabled', !enabled);
      $testBtn.toggleClass('disabled', !enabled);

      // Test API form fields
      $('#contactin-test-api-form input, #contactin-test-api-form textarea').prop('disabled', !enabled);

    },

    /**
     * Show token generation form
     */
    showGenerateTokenForm: function() {
      var name = prompt(contactinIntegrationL10n.tokenPrompt);
      if (name) {
        this.generateToken(name);
      }
    },

    /**
     * Generate a new REST API token via AJAX
     */
    generateToken: function(name) {
      var self = this;
      var data = {
        action: 'contactin_generate_rest_token',
        nonce: contactinIntegrationL10n.nonce,
        name: name,
        routes: []
      };

      $.post(ajaxurl, data, function(response) {
        if (response.success) {
          var token = response.data.token;
          // Show once then immediately reload to refresh token list
          alert(contactinIntegrationL10n.tokenGenerated + '\n\n' + token + '\n\n' + contactinIntegrationL10n.tokenCopyWarning);
          location.reload();
        } else {
          alert(response.data.message || 'Failed to generate token.');
        }
      });
    },

    /**
     * Revoke a REST API token
     */
    revokeToken: function(tokenId) {
      if (!confirm(contactinIntegrationL10n.confirmRevoke)) {
        return;
      }

      var data = {
        action: 'contactin_revoke_rest_token',
        nonce: contactinIntegrationL10n.nonce,
        token_id: tokenId
      };

      $.post(ajaxurl, data, function(response) {
        if (response.success) {
          location.reload();
        } else {
          alert(response.data.message || 'Failed to revoke token.');
        }
      });
    },

    /**
     * Copy text to clipboard
     */
    copyToClipboard: function(text) {
      navigator.clipboard.writeText(text).then(function() {
        alert(contactinIntegrationL10n.copied);
      }).catch(function() {
        alert(contactinIntegrationL10n.copyFailed);
      });
    },

    /**
     * Test API connection with sample data
     */
    testConnection: function() {
      var $form = $('#contactin-test-api-form');
      var $submit = $('#test_submit');
      var $loading = $('#test_loading');
      var $results = $('#test_results');
      var $resultContent = $('#test_result_content');
      var $status = $('<span id="test_status_msg" class="contactin-test-status-msg" style="margin-left:12px;"></span>');
      $('#test_submit').nextAll('.contactin-test-status-msg').remove();
      $('#test_submit').after($status);

      var name = $('#test_name').val();
      var email = $('#test_email').val();
      var message = $('#test_message').val();

      var formData = new FormData();
      formData.append('name', name);
      formData.append('email', email);
      formData.append('message', message);
      formData.append('salutation', $('#test_salutation').val() || '');
      formData.append('subject', $('#test_subject').val() || '');

      var attachmentInput = $('#test_attachment')[0];
      if (attachmentInput && attachmentInput.files && attachmentInput.files[0]) {
        formData.append('attachment', attachmentInput.files[0]);
      }

      // Validation
      if (!name || !email || !message) {
        alert(contactinIntegrationL10n.allFieldsRequired);
        return;
      }

      // Show loading
      $submit.prop('disabled', true);
      $loading.removeClass('cin-hidden');
      $results.addClass('cin-hidden');

      $.ajax({
        url: contactinIntegrationL10n.submitUrl,
        method: 'POST',
        data: formData,
        processData: false,
        contentType: false,
        success: function(response) {
        $submit.prop('disabled', false);
        $loading.addClass('cin-hidden');
        $results.removeClass('cin-hidden');

        if (response && response.success) {
          $status.text(response.message || 'Test request successful!').removeClass('error').addClass('success');
          var html = '<div class="contactin-test-success">';
          html += '<strong style="color:#2d5016;">✓ ' + (response.message || 'Test successful') + '</strong>';
          if (response.id) {
            html += '<p>Message ID: <code>' + response.id + '</code></p>';
          }
          html += '<pre class="contactin-json-pre">' + JSON.stringify(response, null, 2) + '</pre>';
          html += '</div>';
          $resultContent.html(html);
        } else {
          var msg = response && response.message ? response.message : 'Test failed.';
          $status.text(msg).removeClass('success').addClass('error');
          var html = '<div class="contactin-test-error">';
          html += '<strong style="color:#9c1823;">✗ ' + msg + '</strong>';
          html += '<pre class="contactin-json-pre">' + JSON.stringify(response || {}, null, 2) + '</pre>';
          html += '</div>';
          $resultContent.html(html);
        }
      },
      error: function(xhr) {
        $submit.prop('disabled', false);
        $loading.addClass('cin-hidden');
        $results.removeClass('cin-hidden');
        var response = xhr && xhr.responseJSON ? xhr.responseJSON : null;
        var msg = response && response.message ? response.message : 'Request failed';
        $resultContent.html('<div class="contactin-test-error"><strong style="color:#9c1823;">✗ ' + msg + '</strong></div>');
      }
      });
    }
  };



    // Document ready
    $(document).ready(function() {
      // REST API Integration: Attach event listeners
      var $toggleBtn = $('#contactin-toggle-restapi');
      if ($toggleBtn.length) {
        if (typeof window.cinInitToggleButton === 'function') {
          window.cinInitToggleButton({
            buttonId: 'contactin-toggle-restapi',
            statusLabelId: 'contactin-restapi-status-label',
            hiddenFieldId: null,
            ajaxAction: 'contactin_toggle_restapi_service',
            enabledText: 'Disable REST API Service',
            disabledText: 'Enable REST API Service',
            enabledLabel: 'Service Enabled',
            disabledLabel: 'Service Disabled',
            onToggle: function(enabled) {
              ContactINIntegration.setActionItemsEnabled(enabled);
            }
          });
        } else {
          $toggleBtn.on('click', function() {
            ContactINIntegration.toggleRestApiService(this);
          });
        }
      }

      var $copyBtn = $('#contactin-copy-base-url');
      if ($copyBtn.length) {
        $copyBtn.on('click', function() {
          ContactINIntegration.copyToClipboard($(this).data('base-url'));
        });
      }

      // Rate limits save button
      var $saveRateLimitsBtn = $('#contactin-save-rate-limits');
      if ($saveRateLimitsBtn.length) {
        $saveRateLimitsBtn.on('click', function() {
          var value = $('#rate_limit_value').val();
          var unit = $('#rate_limit_unit').val();
          
          // Build POST data based on selected unit
          var postData = {
            action: 'contactin_save_rate_limits',
            nonce: contactinIntegrationL10n.nonce
          };
          
          if (unit === 'minute') {
            postData.rate_limit_per_minute = value;
          } else if (unit === 'hour') {
            postData.rate_limit_per_hour = value;
          } else if (unit === 'day') {
            postData.rate_limit_per_day = value;
          }

          $saveRateLimitsBtn.prop('disabled', true).text('Saving...');
          $.post(ajaxurl, postData, function(response) {
            $saveRateLimitsBtn.prop('disabled', false).text(contactinIntegrationL10n.saveRateLimits || 'Save');
            var $msg = $('#contactin-rate-limits-message');
            if (response && response.success) {
              $msg.text('✓ ' + (response.data.message || 'Rate limit saved')).removeClass('error').addClass('success').removeClass('cin-hidden');
              setTimeout(function() { $msg.addClass('cin-hidden'); }, 3000);
            } else {
              $msg.text('✗ ' + (response.data.message || 'Failed to save')).removeClass('success').addClass('error').removeClass('cin-hidden');
            }
          }).fail(function() {
            $saveRateLimitsBtn.prop('disabled', false).text(contactinIntegrationL10n.saveRateLimits || 'Save');
            $('#contactin-rate-limits-message').text('✗ Network error').addClass('error').removeClass('cin-hidden');
          });
        });
      }

      // Set initial enabled/disabled state for action items
      var restEnabled = $('#contactin-toggle-restapi').data('enabled') == 1;
      ContactINIntegration.setActionItemsEnabled(restEnabled);
    });

})(jQuery);
